const ELEMENT_CORE = Object.freeze({
 fire:['#39121f','#a42e31','#ff8741','#fff1ad'], ice:['#102c50','#2565ab','#7fddff','#eaffff'],
 water:['#102b46','#176db4','#50cafa','#e0faff'], wind:['#103b32','#248b6e','#78edb5','#e8fff1'],
 lightning:['#332452','#8961cc','#f5cc52','#fffce1'], earth:['#322418','#906138','#d8ad64','#fff1c5'],
 neutral:['#16113b','#45408e','#9890ef','#fff0ff']
});
const CORE_KEYS=['chestDeep','chestMid','chestBright','chestStar'];
const mod=(n,m)=>((n%m)+m)%m;
export const ETERNITY_OVERLORD_V2_DEF = Object.freeze({grid:ETERNITY_OVERLORD_V2_GRID,materials:ETERNITY_OVERLORD_V2_MATERIALS,parts:PARTS,
 animate({frame=0,now=0,pose='idle',reducedMotion=false,eternityPhase=1,affinity='neutral'}={}) {
  if(pose==='dead') return {partStates:{hideParts:true},effects:[]};
  const p2=eternityPhase===2, ms=now>0?now:frame*170;
  const tick=(interval)=>reducedMotion?0:Math.floor(ms/interval);
  const p={rearHalo:{frame:mod(tick(125),24)},cloakLeft:{frame:mod(tick(170),12)+(p2?12:0)},cloakRight:{frame:mod(tick(170)+(reducedMotion?0:3),12)+(p2?12:0)},mainBody:{frame:p2?1:0},staffGalaxy:{frame:mod(tick(95),24)},chestCore:{frame:mod(tick(145),12)}};
  if(p2) p.chestCore.overrides=Object.fromEntries(CORE_KEYS.map((k,i)=>[k,(ELEMENT_CORE[affinity]??ELEMENT_CORE.neutral)[i]]));
  const phases=[tick(105),-tick(137),tick(83)];
  for(let i=1;i<=3;i++) for(const side of ['Rear','Front']) p[`lowerRing${i}${side}`]={visible:p2,frame:mod(phases[i-1],24)};
  return {partStates:p,effects:[]};
 }});
